evidence.en:
// A
function getFirst(array) { return array[0]; }

// B
function sumAll(numbers) {
  let sum = 0;
  for (let i = 0; i < numbers.length; i++) sum += numbers[i];
  return sum;
}

// C
function allPairs(numbers) {
  let count = 0;
  for (let i = 0; i < numbers.length; i++)
    for (let j = 0; j < numbers.length; j++) count++;
  return count;
}

// D — worst case: target not present
function findIndex(array, target) {
  for (let i = 0; i < array.length; i++)
    if (array[i] === target) return i;
  return -1;
}

evidence.ru:
// A
function getFirst(array) { return array[0]; }

// B
function sumAll(numbers) {
  let sum = 0;
  for (let i = 0; i < numbers.length; i++) sum += numbers[i];
  return sum;
}

// C
function allPairs(numbers) {
  let count = 0;
  for (let i = 0; i < numbers.length; i++)
    for (let j = 0; j < numbers.length; j++) count++;
  return count;
}

// D — наихудший случай: цели нет в массиве
function findIndex(array, target) {
  for (let i = 0; i < array.length; i++)
    if (array[i] === target) return i;
  return -1;
}

